#include <algorithm>
#include <iostream>
#include <numeric>
#include <vector>
using namespace std;
struct Edge{int u,v; long long w;};
struct DSU{ vector<int> p,sz; DSU(int n):p(n+1),sz(n+1,1){ iota(p.begin(),p.end(),0); } int find(int x){ return p[x]==x?x:p[x]=find(p[x]); } bool unite(int a,int b){ a=find(a); b=find(b); if(a==b) return false; if(sz[a]<sz[b]) swap(a,b); p[b]=a; sz[a]+=sz[b]; return true; }};
int main(){ ios::sync_with_stdio(false); cin.tie(nullptr); int n,m; if(!(cin>>n>>m)) return 0; vector<Edge> e(m); for(auto &x:e) cin>>x.u>>x.v>>x.w; sort(e.begin(),e.end(),[](const Edge&a,const Edge&b){return a.w<b.w;}); DSU dsu(n); long long total=0; int used=0; for(const auto &x:e){ if(dsu.unite(x.u,x.v)){ total+=x.w; used++; if(used==n-1) break; }} if(used==n-1) cout<<total<<'\n'; else cout<<"orz\n"; return 0; }
